/* eslint-disable @typescript-eslint/no-explicit-any */
import React, { useCallback, useState } from 'react';
import { CredentialResponse, GoogleLogin } from '@react-oauth/google';
import { useDispatch } from 'react-redux';
import { message } from 'antd';
import Router from 'next/router';
import { isNull } from 'lodash';
import redirectUrlHandler from 'Utils/helpers/redirectUrlHandler';
import { setKeyByValue } from 'redux/actions/auth';
import { axiosInstance } from 'services/globalInstance';
import { tokenRefreshManager } from 'services/tokenRefreshManager';
import { rollbar } from 'components/common/rollbar';
import TwoFACodeForm from './LoginMainForm/TwoFACodeForm';

interface Props {
  token?: string;
  secret?: string;
  redirectUrl?: string;
}

const decodeJwtEmail = (credential?: string) => {
  if( typeof window !== 'undefined' && credential ){
     const decoded = window.atob(credential.split('.')[1])
     const parsed = JSON.parse(decoded)
     return parsed.email
  }
  return ''
}

const GoogleLoginBtn:React.FC<Props> = ({ token, secret, redirectUrl }) => {
  const dispatch = useDispatch();
  const [isLoading, setIsLoading] = useState(false);
  const [mfaModal, setMfaModal] = useState(false);
  const [googleRes, setGoogleRes] = useState<CredentialResponse>()

  const onGoogleLogin = useCallback(async (response?: CredentialResponse, otp?: string) => {
    setIsLoading(true);
    const d = new Date();
    await fetch(`${process.env.API_URL}/auth/login`, {
      credentials: 'include',
    });
    const email = decodeJwtEmail(response?.credential)
    const isUXCamEmail = true
    const authUrl = isUXCamEmail ? `${process.env.AUTH_API_URL}/google-login` : `${process.env.API_URL}/auth/google-sign-in`
    const data = {
      id_token: response?.credential,
      ...(token && {'token': token}),
      ...(secret && {'secret': secret}),
      otp,
      timezone: d.toString().split('GMT')[1].split(' (')[0],
    };

    await axiosInstance({
      method: 'post',
      url: authUrl,
      data,
      withCredentials: true,
    })
      .then(async (authResponse) => {
        if (
          !isUXCamEmail && (
            typeof authResponse.data.data.isGoogleSignup === 'undefined' ||
            isNull(authResponse.data.data.isGoogleSignup)
          )
        ) {
          dispatch(setKeyByValue('isActivation', true));
          Router.push(
            '/setup?parentType=signup&type=email_activation',
            `/signup/email-activation`
          );
        } else {
          tokenRefreshManager.start(authResponse.data?.data?.expires_at);
          (window as any).dataLayer = (window as any).dataLayer || [];
          (window as any).dataLayer.push({
            event: 'formSubmissionSuccess',
            formId: 'registration-form',
            signupEmail: email,
          });
          if (redirectUrl && !secret) redirectUrlHandler(redirectUrl);
          else window.location.href = `${process.env.REDIRECT_URL}/dashboard`;
        }
      })
      .catch((error) => {
        const errorResponse = error?.response;
        if (errorResponse) {
          if (errorResponse.status === 302)
            message.info(
              'You are already logged in to another account, please refresh your page',
              2.5
            );
          else if (errorResponse?.data?.error?.mfa_required)
              setMfaModal(true)
          else if (errorResponse?.data?.error?.checkEmail){
            dispatch(setKeyByValue('isActivation', true));
            Router.push(
              '/setup?parentType=signup&type=email_activation',
              `/signup/email-activation`
            );
          }
          else if (errorResponse?.data?.error?.message)
            message.error(errorResponse.data.error.message, 2.5);
          else if (error.response.data.error.otp) 
            message.error(error.response.data.error.otp, 2.5);
          else {
            message.error('Something went wrong, please try again later', 2.5);
            rollbar.error('Google login error', error);
          }
        }
        return errorResponse;
      })
      .finally(() => setIsLoading(false))
  }, [dispatch, redirectUrl, secret, token]);

  const handleSubmit = async ({ otp }:{ otp?: string }) => {
    onGoogleLogin(googleRes, otp);
  }

  const responseFailGoogle = () => {
    rollbar.error('Google login failed.')
    message.error('Google login failed.', 2.5);
  }

  const loginSuccess = useCallback( async (response: CredentialResponse) => {
    setGoogleRes(response);
    onGoogleLogin(response)
  }
  , [ onGoogleLogin ])
  
  return (
    <>
    <GoogleLogin 
      onSuccess={ loginSuccess }
      onError={ responseFailGoogle }
      size='large'
    />
    <TwoFACodeForm
        mfaModal={mfaModal}
        handleSubmit={handleSubmit}
        isLoading={isLoading}
        handleMfaModal={setMfaModal}
      />    
    </>
  );
};
export default GoogleLoginBtn;
